export const getLegalDocument = (documentType, language = "en") => {
  const documents = normalizeLanguage(language) === "uk" ? LEGAL_DOCUMENTS_UK : LEGAL_DOCUMENTS;
  return Object.hasOwn(documents, documentType) ? documents[documentType] : documents.privacy;
};

